import random
def estimate_pi(n):
    inside = 0
    for _ in range(n):
        x, y = random.random(), random.random()
        if x*x + y*y <= 1.0:
            inside += 1
    return 4.0 * inside / n

print(estimate_pi(1_000_000))  # near 3.14159

def tritium_margin(tbr):
    return tbr - 1.0

def test_tritium_margin():
    assert tritium_margin(1.8) == 0.8
    assert tritium_margin(1.0) == 0.0
